const int MAXN = 100005;

vector<int> adj[MAXN];
vector<bool> visited(MAXN);

bool dfs(int u, int target) {
    stack<int> st;
    st.push(u);
    visited[u] = true;
    while (!st.empty()) {
        int curr = st.top(); st.pop();
        if (curr == target) return true;
        for (int v : adj[curr]) {
            if (!visited[v]) {
                visited[v] = true;
                st.push(v);
            }
        }
    }
    return false;
}

