    int n = a.size(), m = b.size();
    vector<vector<int>> dp(2, vector<int>(m + 1, 0));
    for (int i = 1; i <= n; ++i) {
        int cur = i % 2, prev = 1 - cur;
        for (int j = 1; j <= m; ++j) {
            if (a[i - 1] == b[j - 1])
                dp[cur][j] = dp[prev][j - 1] + 1;
            else
                dp[cur][j] = max(dp[prev][j], dp[cur][j - 1]);
        }
    }
    cout << dp[n % 2][m] << endl;
    return 0;
}

