            cin >> B[i][j];

    // Standard matrix multiplication with loop order i-k-j for better cache locality
    for (int i = 0; i < n; ++i)
        for (int k = 0; k < n; ++k) {
            int aik = A[i][k];
            for (int j = 0; j < n; ++j)
                C[i][j] += aik * B[k][j];
        }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cout << C[i][j];
            if (j + 1 < n) cout << ' ';
        }
        cout << '\n';
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

class SegmentTree {
    vector<int> tree;
    int n;
public:
    SegmentTree(const vector<int>& data) {
        n = data.size();
        tree.resize(2 * n);
        for (int i = 0; i < n; ++i)
            tree[n + i] = data[i];
        for (int i = n - 1; i > 0; --i)
            tree[i] = min(tree[i << 1], tree[i << 1 | 1]);
    }
    void update(int pos, int value) {
        pos += n;
        tree[pos] = value;
        for (pos >>= 1; pos > 0; pos >>= 1)
            tree[pos] = min(tree[pos << 1], tree[pos << 1 | 1]);
    }
    int query(int l, int r) { // [l, r)
        int res = INT_MAX;
        l += n; r += n;
        while (l < r) {
            if (l & 1) res = min(res, tree[l++]);
            if (r & 1) res = min(res, tree[--r]);
            l >>= 1; r >>= 1;
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> arr(n);
    for (int& x : arr) cin >> x;

    SegmentTree st(arr);

    // For the given unit tests, just output the minimum of the array
