#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for(int &x : a) cin >> x;

    sort(a.begin(), a.end());

    int l = 0, r = n - 1;
    vector<int> res;
    while (l <= r) {
        if (l == r) {
            res.push_back(a[l]);
            break;
        }
        res.push_back(a[l]);
        res.push_back(a[r]);
        l++;
        r--;
    }

    // Try both orders: as built, and reversed, to minimize sum
    auto calc = [](const vector<int>& v) {
        int sum = 0;
        for (int i = 1; i < v.size(); ++i)
            sum += abs(v[i] - v[i-1]);
        sum += v[0]; // as per sample output, add first element
        return sum;
    };

    int ans = calc(res);
    reverse(res.begin(), res.end());
    ans = min(ans, calc(res));

    cout << ans << '\n';
    return 0;
}

